// IdentityServiceServer is the server API for IdentityService service.
// All implementations must embed UnimplementedIdentityServiceServer
// for forward compatibility.
type IdentityServiceServer interface {
	// Authentication
	BeginOAuthLogin(context.Context, *BeginOAuthLoginRequest) (*BeginOAuthLoginResponse, error)
	OAuthLogin(context.Context, *OAuthLoginRequest) (*OAuthLoginResponse, error)
	RedeemOAuthCode(context.Context, *RedeemOAuthCodeRequest) (*RedeemOAuthCodeResponse, error)
	PasswordSignup(context.Context, *PasswordSignupRequest) (*PasswordSignupResponse, error)
	PasswordLogin(context.Context, *PasswordLoginRequest) (*PasswordLoginResponse, error)
	// Passwordless email login (OTP code + magic link)
	RequestEmailLoginCode(context.Context, *RequestEmailLoginCodeRequest) (*RequestEmailLoginCodeResponse, error)
	VerifyEmailLoginCode(context.Context, *VerifyEmailLoginCodeRequest) (*VerifyEmailLoginCodeResponse, error)
	RequestMagicLink(context.Context, *RequestMagicLinkRequest) (*RequestMagicLinkResponse, error)
	RedeemMagicLink(context.Context, *RedeemMagicLinkRequest) (*RedeemMagicLinkResponse, error)
	// Phone verification (SMS OTP) — proves the authenticated caller owns a phone number
	RequestPhoneVerification(context.Context, *RequestPhoneVerificationRequest) (*RequestPhoneVerificationResponse, error)
	VerifyPhoneCode(context.Context, *VerifyPhoneCodeRequest) (*VerifyPhoneCodeResponse, error)
	// Session / Token Auth
	GetCurrentUser(context.Context, *GetCurrentUserRequest) (*GetCurrentUserResponse, error)
	RefreshToken(context.Context, *RefreshTokenRequest) (*RefreshTokenResponse, error)
	Logout(context.Context, *LogoutRequest) (*LogoutResponse, error)
	// Self-service profile
	UpdateProfile(context.Context, *UpdateProfileRequest) (*UpdateProfileResponse, error)
	// Password Management
	ChangePassword(context.Context, *ChangePasswordRequest) (*ChangePasswordResponse, error)
	RequestPasswordReset(context.Context, *RequestPasswordResetRequest) (*RequestPasswordResetResponse, error)
	ConfirmPasswordReset(context.Context, *ConfirmPasswordResetRequest) (*ConfirmPasswordResetResponse, error)
	// Email Verification
	SendEmailVerification(context.Context, *SendEmailVerificationRequest) (*SendEmailVerificationResponse, error)
	VerifyEmail(context.Context, *VerifyEmailRequest) (*VerifyEmailResponse, error)
	// Email Change (primary-email rotation, double-opt-in)
	RequestEmailChange(context.Context, *RequestEmailChangeRequest) (*RequestEmailChangeResponse, error)
	ConfirmEmailChange(context.Context, *ConfirmEmailChangeRequest) (*ConfirmEmailChangeResponse, error)
	// Identity Verification (document + selfie via pluggable provider)
	BeginIdentityVerification(context.Context, *BeginIdentityVerificationRequest) (*BeginIdentityVerificationResponse, error)
	GetIdentityVerificationStatus(context.Context, *GetIdentityVerificationStatusRequest) (*GetIdentityVerificationStatusResponse, error)
	// Admin help (replaces self-serve ForgotPassword)
	RequestAdminHelp(context.Context, *RequestAdminHelpRequest) (*RequestAdminHelpResponse, error)
	ListHelpRequests(context.Context, *ListHelpRequestsRequest) (*ListHelpRequestsResponse, error)
	ResolveHelpRequest(context.Context, *ResolveHelpRequestRequest) (*ResolveHelpRequestResponse, error)
	// Passkey / WebAuthn
	BeginPasskeyRegistration(context.Context, *BeginPasskeyRegistrationRequest) (*BeginPasskeyRegistrationResponse, error)
	CompletePasskeyRegistration(context.Context, *CompletePasskeyRegistrationRequest) (*CompletePasskeyRegistrationResponse, error)
	BeginPasskeyLogin(context.Context, *BeginPasskeyLoginRequest) (*BeginPasskeyLoginResponse, error)
	CompletePasskeyLogin(context.Context, *CompletePasskeyLoginRequest) (*CompletePasskeyLoginResponse, error)
	ListPasskeys(context.Context, *ListPasskeysRequest) (*ListPasskeysResponse, error)
	DeletePasskey(context.Context, *DeletePasskeyRequest) (*DeletePasskeyResponse, error)
	// QR Login (cross-device authorization)
	InitiateQrLogin(context.Context, *InitiateQrLoginRequest) (*InitiateQrLoginResponse, error)
	GetQrLoginSession(context.Context, *GetQrLoginSessionRequest) (*GetQrLoginSessionResponse, error)
	ApproveQrLogin(context.Context, *ApproveQrLoginRequest) (*ApproveQrLoginResponse, error)
	PollQrLogin(context.Context, *PollQrLoginRequest) (*PollQrLoginResponse, error)
	// 2FA TOTP
	BeginTotpSetup(context.Context, *BeginTotpSetupRequest) (*BeginTotpSetupResponse, error)
	VerifyTotpSetup(context.Context, *VerifyTotpSetupRequest) (*VerifyTotpSetupResponse, error)
	DisableTotp(context.Context, *DisableTotpRequest) (*DisableTotpResponse, error)
	VerifyTotp(context.Context, *VerifyTotpRequest) (*VerifyTotpResponse, error)
	RegenerateRecoveryCodes(context.Context, *RegenerateRecoveryCodesRequest) (*RegenerateRecoveryCodesResponse, error)
	// Session management
	ListMySessions(context.Context, *ListMySessionsRequest) (*ListMySessionsResponse, error)
	RevokeSession(context.Context, *RevokeSessionRequest) (*RevokeSessionResponse, error)
	RevokeAllSessions(context.Context, *RevokeAllSessionsRequest) (*RevokeAllSessionsResponse, error)
	SignOutEverywhere(context.Context, *SignOutEverywhereRequest) (*SignOutEverywhereResponse, error)
	// Audit log
	ListAuditEvents(context.Context, *ListAuditEventsRequest) (*ListAuditEventsResponse, error)
	// Users
	CreateUser(context.Context, *CreateUserRequest) (*CreateUserResponse, error)
	GetUser(context.Context, *GetUserRequest) (*GetUserResponse, error)
	UpdateUser(context.Context, *UpdateUserRequest) (*UpdateUserResponse, error)
	DeleteUser(context.Context, *DeleteUserRequest) (*DeleteUserResponse, error)
	// Admin-only paginated user listing — supports filters and search.
	ListUsers(context.Context, *ListUsersRequest) (*ListUsersResponse, error)
	// Groups (formerly WorkingGroup — graph DB type still WorkingGroup)
	CreateGroup(context.Context, *CreateGroupRequest) (*CreateGroupResponse, error)
	UpdateGroup(context.Context, *UpdateGroupRequest) (*UpdateGroupResponse, error)
	DeleteGroup(context.Context, *DeleteGroupRequest) (*DeleteGroupResponse, error)
	ListGroups(context.Context, *ListGroupsRequest) (*ListGroupsResponse, error)
	// Membership (graph edges)
	AddGroupMember(context.Context, *AddGroupMemberRequest) (*AddGroupMemberResponse, error)
	RemoveGroupMember(context.Context, *RemoveGroupMemberRequest) (*RemoveGroupMemberResponse, error)
	ListGroupMembers(context.Context, *ListGroupMembersRequest) (*ListGroupMembersResponse, error)
	// Organization signup (mode=multi only — returns Unimplemented in
	// mode=single). Creates a new tenant in tenant-shard-db, registers
	// the admin user globally, and creates the identity-layer
	// Organization + admin User rows scoped to the new tenant.
	OrganizationSignup(context.Context, *OrganizationSignupRequest) (*OrganizationSignupResponse, error)
	// Tenant domains (redesign). Authenticated, project-scoped, and gated
	// on the caller being an owner/admin member of the target tenant — with
	// one exception: VerifyDomain on a still-latent tenant that has no
	// members yet is open, so the first verifier becomes its owner.
	// Available only on the postgres control-plane driver; entdb/memory
	// deployments return Unimplemented.
	CreateDomain(context.Context, *CreateDomainRequest) (*CreateDomainResponse, error)
	VerifyDomain(context.Context, *VerifyDomainRequest) (*VerifyDomainResponse, error)
	ListTenantDomains(context.Context, *ListTenantDomainsRequest) (*ListTenantDomainsResponse, error)
	// Tenant membership (redesign). Authenticated, project-scoped, and —
	// except for AcceptTenantInvitation — gated on the caller being an
	// owner/admin member of the target tenant. AcceptTenantInvitation is the
	// redeemer's own action: any authenticated caller may redeem a token, but
	// only for an invitation addressed to their own account email. Available
	// only on the postgres control-plane driver; entdb/memory deployments
	// return Unimplemented.
	CreateTenantInvitation(context.Context, *CreateTenantInvitationRequest) (*CreateTenantInvitationResponse, error)
	AcceptTenantInvitation(context.Context, *AcceptTenantInvitationRequest) (*AcceptTenantInvitationResponse, error)
	ListTenantInvitations(context.Context, *ListTenantInvitationsRequest) (*ListTenantInvitationsResponse, error)
	ListTenantMembers(context.Context, *ListTenantMembersRequest) (*ListTenantMembersResponse, error)
	RemoveTenantMember(context.Context, *RemoveTenantMemberRequest) (*RemoveTenantMemberResponse, error)
	// Admin user management (caller must have role=admin). Enforced in the
	// servicer via _require_admin(ctx); all admin RPCs audit-log their actions.
	InviteUser(context.Context, *InviteUserRequest) (*InviteUserResponse, error)
	AcceptInvitation(context.Context, *AcceptInvitationRequest) (*AcceptInvitationResponse, error)
	DeactivateUser(context.Context, *DeactivateUserRequest) (*DeactivateUserResponse, error)
	ReactivateUser(context.Context, *ReactivateUserRequest) (*ReactivateUserResponse, error)
	ResetUserPassword(context.Context, *ResetUserPasswordRequest) (*ResetUserPasswordResponse, error)
	SetUserQuota(context.Context, *SetUserQuotaRequest) (*SetUserQuotaResponse, error)
	// Control-plane admin (redesign). PLATFORM-operator RPCs that provision
	// projects/tenants/credentials out-of-band. Authenticated by the shared
	// admin secret in the "X-Admin-Secret" header (NOT a user JWT); disabled
	// (UNIMPLEMENTED) unless GATEWAY_ADMIN_API_SECRET is set.
	AdminCreateProject(context.Context, *AdminCreateProjectRequest) (*AdminCreateProjectResponse, error)
	AdminCreateProjectCredential(context.Context, *AdminCreateProjectCredentialRequest) (*AdminCreateProjectCredentialResponse, error)
	AdminAddProjectAuthDomain(context.Context, *AdminAddProjectAuthDomainRequest) (*AdminAddProjectAuthDomainResponse, error)
	AdminCreateTenant(context.Context, *AdminCreateTenantRequest) (*AdminCreateTenantResponse, error)
	AdminAddTenantAdmin(context.Context, *AdminAddTenantAdminRequest) (*AdminAddTenantAdminResponse, error)
	mustEmbedUnimplementedIdentityServiceServer()
}

